INSERT INTO destination_translation (destination_id, lang, name, tagline, description, best_time_to_visit) SELECT id, 'ro', 'Japonia', 'Nopți de neon, temple liniștite și arta micilor detalii.', 'Japonia este locul unde orașe ultramoderne stau lângă altare vechi de o mie de ani. Fiecare tren vine la timp, fiecare masă e o mică ceremonie, iar fiecare anotimp pictează țara într-o altă culoare.', 'Sfârșitul lui martie - mai (cireșii în floare) și octombrie - noiembrie (frunzele de toamnă)' FROM destination WHERE slug = 'japan';
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Un oraș de 14 milioane de locuitori care încă pare o colecție de cartiere mici, fiecare cu personalitatea lui.', 'Tokyo are mai multe restaurante cu stele Michelin decât orice alt oraș din lume - iar unele sunt doar niște tejghele minuscule, cu mai puțin de 10 locuri.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Intersecția Shibuya noaptea', 'Privește până la 3.000 de oameni traversând deodată de pe terasa Shibuya Sky, apoi alătură-te și tu mulțimii.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Senso-ji la răsărit', 'Cel mai vechi templu din Tokyo, în Asakusa, liniștit și aurit înainte să sosească mulțimile.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Mic dejun la Tsukiji Outer Market', 'Tamagoyaki, sushi proaspăt și scoici la grătar, mâncate în picioare lângă tarabe.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Mergi desculț prin apă și prin camere cu oglinzi într-un muzeu imersiv de artă digitală.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Muntele Fuji / Hakone', 'Izvoare termale, o corabie de pirați pe lacul Ashi și - într-o zi senină - Fuji în toată splendoarea lui.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Panorama orașului Tokyo' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Felinare seara' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.sort_order = 1;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Muntele Fuji văzut de la Pagoda Chureito' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo' AND x.sort_order = 2;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Vechea capitală imperială: case de lemn machiya, grădini cu mușchi și felinare care strălucesc pe ulițe înguste.', 'Kyoto are peste 1.600 de temple budiste și aproximativ 400 de altare șintoiste. A fost cruțat de bombardamente în al Doilea Război Mondial datorită valorii sale culturale.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', NULL, 'Plimbă-te la răsărit printre miile de porți torii.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Pădurea de bambus Arashiyama și Tenryu-ji', 'Bambuși uriași, apoi o grădină zen aflată în patrimoniul mondial UNESCO.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Gion la apus', 'Plimbă-te pe străzile luminate de felinare și poate zărești o geiko sau o maiko în drum spre o întâlnire.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Kinkaku-ji, Pavilionul de Aur', 'Un templu acoperit cu foiță de aur, oglindit perfect în iazul din fața lui.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'O ceremonie a ceaiului sau o cină kaiseki', 'Încetinește ritmul cu un matcha într-o cameră cu tatami sau cu un festin sezonier cu multe feluri.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Pagoda Yasaka' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.sort_order = 0;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Felinare în Gion' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto' AND x.sort_order = 1;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Bucătăria Japoniei: gălăgioasă, prietenoasă și obsedată de street food.', 'Motto-ul neoficial al orașului Osaka este „kuidaore” - mănâncă până cazi.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Tur de street food în Dotonbori', 'Takoyaki, okonomiyaki și kushikatsu sub celebra reclamă Glico cu omulețul care aleargă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Castelul Osaka', 'Urcă în castel pentru priveliștea asupra orașului și plimbă-te pe lângă șanțurile cu apă mărginite de cireși.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Piața Kuromon', 'Frigărui de wagyu la grătar și căpșuni uriașe, direct de la tarabă.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Excursie de o zi la Nara', 'Înclină-te în fața căprioarelor prietenoase și vezi statuia uriașă a lui Buddha din Todai-ji.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Umeda Sky Building la apus', 'Un observator în aer liber, o „grădină plutitoare” la 173 m deasupra orașului.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Osaka noaptea' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Partea tropicală a Japoniei: apă turcoaz, recife de corali și o cultură insulară relaxată.', 'Okinawa este una dintre „Zonele Albastre” ale lumii, cu unul dintre cele mai mari numere de centenari de pe Pământ.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Snorkeling în Insulele Kerama', 'Una dintre cele mai limpezi ape din lume, cu broaște țestoase marine drept companie.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Acvariul Churaumi', 'Rechini-balenă care alunecă prin fața unuia dintre cele mai mari geamuri de acvariu din lume.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Castelul Shuri', 'Reședința lăcuită în roșu a vechiului Regat Ryukyu.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Cu mașina pe podul spre insula Kouri', 'Un pod de doi kilometri care pare să plutească deasupra apelor turcoaz, puțin adânci.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Bucătărie tradițională din Okinawa', 'Goya champuru și cartof dulce mov - dieta longevității.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Coasta din Okinawa' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa' AND x.sort_order = 0;
INSERT INTO place_translation (place_id, lang, name, description, fun_fact) SELECT p.id, 'ro', NULL, 'Nordul sălbatic al Japoniei: zăpadă pufoasă, câmpuri de lavandă și izvoare termale aburinde.', 'În Niseko, pe Hokkaido, cad în jur de 15 metri de zăpadă pe sezon - una dintre cele mai pufoase zăpezi de pe planetă.' FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido';
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Schi sau snowboard în Niseko', 'Zăpadă pufoasă celebră în toată lumea, cu Muntele Yotei înălțându-se în spatele pârtiilor.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 1;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Festivalul Zăpezii din Sapporo', 'Sculpturi uriașe de gheață în fiecare februarie.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 2;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Câmpurile de lavandă din Furano', 'Dealuri mov de la sfârșitul lui iunie până la începutul lui august.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 3;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Onsen în Noboribetsu', 'Relaxează-te în izvoare cu sulf, lângă aburinda „Vale a Iadului”.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 4;
INSERT INTO activity_translation (activity_id, lang, title, description) SELECT x.id, 'ro', 'Fructe de mare proaspete în Otaru', 'Boluri cu uni, crab și icre de somon într-un orășel-port cu canale.' FROM activity x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.rank_no = 5;
INSERT INTO image_translation (image_id, lang, caption) SELECT x.id, 'ro', 'Hokkaido iarna' FROM image x JOIN place p ON p.id = x.place_id JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido' AND x.sort_order = 0;
